/**
 * GUIKit Memory-Safe GUI Loader
 * 
 * Loads GUI JSON files with memory checking
 * Displays error on TFT if GUI cannot fit in memory
 * 
 * Generated by Mistral Vibe
 * Date: 2026-08-15
 */

#ifndef GUI_LOADER_MEMORY_SAFE_H
#define GUI_LOADER_MEMORY_SAFE_H

#include <stdint.h>
#include <stdbool.h>
#include "gui_memory_checker.h"

// Forward declarations
class TFT_ST7789;
void* gui_loader_parse_json(const char* json);

// ============================================================================
// Memory-Safe GUI Loading Functions
// ============================================================================

/**
 * Load GUI from JSON string with memory checking
 * 
 * @param json JSON string containing GUI definition
 * @param tft TFT display instance (for error messages)
 * @return Pointer to GUI structure, or NULL if cannot fit in memory
 * @note Caller must free the returned pointer
 */
void* gui_loader_load_with_memory_check(const char* json, TFT_ST7789* tft);

/**
 * Load GUI from file with memory checking
 * 
 * @param filepath Path to GUI JSON file
 * @param tft TFT display instance (for error messages)
 * @return Pointer to GUI structure, or NULL if cannot fit in memory
 * @note Caller must free the returned pointer
 */
void* gui_loader_load_file_with_memory_check(const char* filepath, TFT_ST7789* tft);

/**
 * Load GUI from SD card with memory checking
 * 
 * @param filename GUI filename (without path)
 * @param tft TFT display instance (for error messages)
 * @return Pointer to GUI structure, or NULL if cannot fit in memory
 * @note Caller must free the returned pointer
 */
void* gui_loader_load_sd_with_memory_check(const char* filename, TFT_ST7789* tft);

/**
 * Load GUI from WebDAV with memory checking
 * 
 * @param filename GUI filename
 * @param tft TFT display instance (for error messages)
 * @return Pointer to GUI structure, or NULL if cannot fit in memory
 * @note Caller must free the returned pointer
 */
void* gui_loader_load_webdav_with_memory_check(const char* filename, TFT_ST7789* tft);

// ============================================================================
// GUI Memory Information Functions
// ============================================================================

/**
 * Get detailed memory information for a GUI JSON
 * 
 * @param json JSON string containing GUI definition
 * @return GuiMemoryStats with memory information
 */
GuiMemoryStats gui_loader_get_memory_info(const char* json);

/**
 * Get memory information for a GUI file
 * 
 * @param filepath Path to GUI JSON file
 * @return GuiMemoryStats with memory information
 */
GuiMemoryStats gui_loader_get_memory_info_file(const char* filepath);

/**
 * Check if current system has enough memory for a GUI
 * 
 * @param json JSON string containing GUI definition
 * @return true if GUI can be loaded, false otherwise
 */
bool gui_loader_has_enough_memory(const char* json);

// ============================================================================
// Configuration
// ============================================================================

// Enable/disable memory checking (for debugging)
#define GUI_LOADER_MEMORY_CHECK_ENABLED 1

// Maximum GUI size in bytes (to prevent loading huge files)
#define GUI_LOADER_MAX_FILE_SIZE (32 * 1024)  // 32 KB

#endif // GUI_LOADER_MEMORY_SAFE_H
